using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Reflection;
using System.Xml.Linq;
using MelloCharts;

public static class IntegrationTests {
  static int passed,failed;
  static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+(ex.InnerException??ex).Message);}}
  static void Is(bool condition,string message){if(!condition)throw new Exception(message);}
  static object Call(string name,params object[] args){MethodInfo m=typeof(PowerPointBridge).GetMethods().FirstOrDefault(x=>x.Name==name && x.GetParameters().Length==args.Length);Is(m!=null,"Método ausente: "+name);return m.Invoke(null,args);}
  static void Reject(Action action){try{action();}catch{return;}throw new Exception("Operação insegura aceita");}
  static void Near(double a,double b){Is(Math.Abs(a-b)<.001,"Geometria divergente "+a+" / "+b);}
  [STAThread] public static int Main(){
    Test("slide placement respects widescreen standard and custom canvases",delegate{foreach(double[] page in new[]{new[]{960.0,540},new[]{720.0,540},new[]{300.0,200},new[]{540.0,960}}){dynamic box=Call("FitBounds",page[0],page[1]);Near((double)box.Width/(double)box.Height,16.0/9);Is(box.Left>=0 && box.Top>=0 && box.Left+box.Width<=page[0] && box.Top+box.Height<=page[1],"Fora do slide");}Reject(delegate{Call("FitBounds",Double.NaN,540.0);});});
    Test("new charts fit the actual slide size",delegate{NativeApp app=new NativeApp();app.ActivePresentation.PageSetup.SlideWidth=720;app.ActivePresentation.PageSetup.SlideHeight=540;Call("InsertOrUpdate",app,ChartCore.Example("buildup"),null);FakeShape shape=app.ActiveWindow.View.Slide.Shapes[1];Is(shape.Left>=0 && shape.Top>=0 && shape.Left+shape.Width<=720 && shape.Top+shape.Height<=540,"Gráfico fora do slide");Is(app.UndoEntries==1,"Entrada de desfazer ausente");});
    Test("editor context remains on its original slide",delegate{NativeApp app=new NativeApp();dynamic session=Call("CaptureContext",app);FakeSlide first=app.ActiveWindow.View.Slide;FakeSlide other=app.ActivePresentation.AddSlide(77);app.ActiveWindow.View.Slide=other;Is(Object.ReferenceEquals(Call("ResolveContext",app,(object)session),first),"Destino seguiu a seleção");});
    Test("context rejects another presentation even with matching slide ids",delegate{NativeApp app=new NativeApp();object context=Call("CaptureContext",app);NativeDeck original=app.ActivePresentation;NativeDeck another=new NativeDeck();app.Presentations.Items.Add(another);app.ActivePresentation=another;app.ActiveWindow.View.Slide=another.Slides.Items[0];Reject(delegate{Call("ResolveContext",app,context);});Is(original.Slides.Items[0].Shapes.Count==0 && another.Slides.Items[0].Shapes.Count==0,"Apresentação alterada");});
    Test("closed presentation and deleted slide invalidate editor context",delegate{NativeApp app=new NativeApp();object context=Call("CaptureContext",app);app.ActivePresentation.Slides.Items.Clear();Reject(delegate{Call("ResolveContext",app,context);});app=new NativeApp();context=Call("CaptureContext",app);app.Presentations.Items.Clear();Reject(delegate{Call("ResolveContext",app,context);});});
    Test("child selection resolves its parent chart",delegate{NativeApp app=new NativeApp();Call("InsertOrUpdate",app,ChartCore.Example("columns"),null);FakeShape group=app.ActiveWindow.View.Slide.Shapes[1];FakeShape child=new FakeShape(app.ActiveWindow.View.Slide.Shapes,999,17,0,0,10,10);child.ParentGroup=group;app.ActiveWindow.Selection.Items=new[]{child};app.ActiveWindow.Selection.HasChildShapeRange=true;ChartReference selected=PowerPointBridge.Selected(app);Is(selected.ShapeId==group.Id,"Grupo pai não localizado");});
    Test("ambiguous and unrelated selections are rejected",delegate{NativeApp app=new NativeApp();Call("InsertOrUpdate",app,ChartCore.Example("columns"),null);Call("InsertOrUpdate",app,ChartCore.Example("buildup"),null);app.ActiveWindow.Selection.Items=app.ActiveWindow.View.Slide.Shapes.Items.ToArray();Reject(delegate{PowerPointBridge.Selected(app);});app.ActiveWindow.Selection.Items=new[]{new FakeShape(new FakeShapes(),999,1,0,0,10,10)};Reject(delegate{PowerPointBridge.Selected(app);});});
    Test("duplicate preserves model and geometry without deleting original",delegate{NativeApp app=new NativeApp();Call("InsertOrUpdate",app,ChartCore.Example("columns"),null);FakeShape original=app.ActiveWindow.View.Slide.Shapes[1];original.Width=400;original.Height=225;app.ActiveWindow.Selection.Items=new[]{original};ChartReference copy=(ChartReference)Call("DuplicateSelected",app);Is(app.ActiveWindow.View.Slide.Shapes.Count==2,"Duplicação não preservou original");FakeShape duplicate=app.ActiveWindow.View.Slide.Shapes.Items.Single(s=>s.Id==copy.ShapeId);Near(duplicate.Width,400);Near(duplicate.Height,225);Is(original.Name!=duplicate.Name && ChartCore.Serialize(Metadata.Read(original))==ChartCore.Serialize(Metadata.Read(duplicate)),"Cópia perdeu dados ou identidade");});
    Test("failed duplication preserves original",delegate{NativeApp app=new NativeApp();Call("InsertOrUpdate",app,ChartCore.Example("columns"),null);FakeShape original=app.ActiveWindow.View.Slide.Shapes[1];app.ActiveWindow.Selection.Items=new[]{original};app.ActiveWindow.View.Slide.Shapes.FailTags=true;Reject(delegate{Call("DuplicateSelected",app);});Is(app.ActiveWindow.View.Slide.Shapes.Count==1 && Object.ReferenceEquals(original,app.ActiveWindow.View.Slide.Shapes[1]),"Original afetado");});
    Test("duplicate keeps native customizations and creates an independent identity",delegate{NativeApp app=new NativeApp();Call("InsertOrUpdate",app,ChartCore.Example("columns"),null);FakeShape original=app.ActiveWindow.View.Slide.Shapes[1];original.ManualStyle="Cor, fonte e animação ajustadas no PowerPoint";app.ActiveWindow.Selection.Items=new[]{original};ChartReference reference=(ChartReference)Call("DuplicateSelected",app);FakeShape copy=app.ActiveWindow.View.Slide.Shapes.Items.Single(s=>s.Id==reference.ShapeId);Is(copy.ManualStyle==original.ManualStyle,"Cópia perdeu os ajustes nativos");Is(copy.Name!=original.Name,"Cópia compartilha identidade");});
    Test("fit selection keeps shape identity and chart metadata",delegate{NativeApp app=new NativeApp();Call("InsertOrUpdate",app,ChartCore.Example("columns"),null);FakeShape shape=app.ActiveWindow.View.Slide.Shapes[1];int id=shape.Id;string data=ChartCore.Serialize(Metadata.Read(shape));shape.Left=-80;shape.Top=300;shape.Width=1300;shape.Height=100;shape.Rotation=45;app.ActiveWindow.Selection.Items=new[]{shape};Call("FitSelected",app);Is(shape.Id==id && ChartCore.Serialize(Metadata.Read(shape))==data,"Ajuste recriou o gráfico");Near(shape.Width/shape.Height,16.0/9);Near(shape.Rotation,0);Is(shape.Left>=0 && shape.Top>=0 && shape.Left+shape.Width<=960 && shape.Top+shape.Height<=540,"Ajuste fora do slide");});
    Test("ribbon declares native actions and contextual enable callbacks",delegate{XDocument xml=XDocument.Parse(new Connect().GetCustomUI("Microsoft.PowerPoint.Presentation"));XNamespace ns="http://schemas.microsoft.com/office/2009/07/customui";foreach(string method in new[]{"DuplicateChart","FitChart","ShowDiagnostics"})Is(xml.Descendants(ns+"button").Any(e=>(string)e.Attribute("onAction")==method),"Comando ausente: "+method);Is((string)xml.Root.Attribute("onLoad")=="OnRibbonLoad","Carga da ribbon ausente");Is(xml.Descendants(ns+"button").Any(e=>(string)e.Attribute("getEnabled")=="CanEdit"),"Estado contextual ausente");foreach(var element in xml.Descendants(ns+"button"))foreach(string attr in new[]{"onAction","getEnabled","getImage"}){string name=(string)element.Attribute(attr);if(name!=null)Is(typeof(Connect).GetMethod(name)!=null,"Callback ausente: "+name);}});
    Test("contextual actions disable without slide or supported selection",delegate{Connect connect=new Connect();MethodInfo create=typeof(Connect).GetMethod("CanCreate"),edit=typeof(Connect).GetMethod("CanEdit");Is(create!=null && edit!=null,"Callbacks de habilitação ausentes");Is(!(bool)create.Invoke(connect,new object[]{null}) && !(bool)edit.Invoke(connect,new object[]{null}),"Comando sem host habilitado");NativeApp app=new NativeApp();Array custom=new object[0];connect.OnConnection(app,0,null,ref custom);Is((bool)create.Invoke(connect,new object[]{null}) && !(bool)edit.Invoke(connect,new object[]{null}),"Estado inicial incorreto");Call("InsertOrUpdate",app,ChartCore.Example("buildup"),null);app.ActiveWindow.Selection.Items=new[]{app.ActiveWindow.View.Slide.Shapes[1]};Is((bool)edit.Invoke(connect,new object[]{null}),"Edição válida desabilitada");connect.OnDisconnection(0,ref custom);});
    Test("diagnostics reads installation state without document content",delegate{Type type=typeof(Connect).Assembly.GetType("MelloCharts.InstallationHealth");Is(type!=null,"Diagnóstico ausente");string report=(string)type.GetMethod("Collect").Invoke(null,new object[]{"0.5.0"});Is(report.Contains("0.5.0") && report.Contains("LoadBehavior") && report.Contains("ativação"),"Relatório incompleto");Is(!report.Contains("ActivePresentation") && !report.Contains("São José"),"Relatório contém dados do documento");});
    Test("ribbon refresh reacts to selection changes without repeated invalidation",delegate{Connect connect=new Connect();NativeRibbon ribbon=new NativeRibbon();NativeApp app=new NativeApp();Array custom=new object[0];connect.OnConnection(app,0,null,ref custom);connect.OnRibbonLoad(ribbon);int first=ribbon.Invalidations;MethodInfo refresh=typeof(Connect).GetMethod("RefreshRibbon",BindingFlags.NonPublic|BindingFlags.Instance);refresh.Invoke(connect,null);Is(ribbon.Invalidations==first,"Invalidação redundante");Call("InsertOrUpdate",app,ChartCore.Example("buildup"),null);app.ActiveWindow.Selection.Items=new[]{app.ActiveWindow.View.Slide.Shapes[1]};refresh.Invoke(connect,null);Is(ribbon.Invalidations==first+1,"Seleção não atualizou a ribbon");connect.OnDisconnection(0,ref custom);});
    Test("chart commands have distinct icons",delegate{List<string> hashes=new List<string>();foreach(string id in new[]{"Build","Waterfall","Columns","Edit","Duplicate","Fit","Diagnostics","Help"})using(Bitmap icon=RibbonIcons.Create(id))using(System.IO.MemoryStream stream=new System.IO.MemoryStream()){Is(icon.Width==32 && icon.Height==32,"Tamanho incorreto");icon.Save(stream,System.Drawing.Imaging.ImageFormat.Png);hashes.Add(Convert.ToBase64String(stream.ToArray()));}Is(hashes.Distinct().Count()==8,"Ícones repetidos");});
    Test("editor detects unsaved data and appearance changes",delegate{using(EditorForm editor=new EditorForm(null,ChartCore.Example("columns"),null)){Is(!editor.HasPendingChanges,"Documento inicial marcado como alterado");var palette=(System.Windows.Forms.ComboBox)typeof(EditorForm).GetField("palette",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(editor);palette.SelectedIndex=1;Is(editor.HasPendingChanges,"Aparência não marcada como alterada");palette.SelectedIndex=0;Is(!editor.HasPendingChanges,"Reversão não detectada");var grid=(System.Windows.Forms.DataGridView)typeof(EditorForm).GetField("grid",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(editor);grid.Rows[0].Cells["actual"].Value="inválido";Is(editor.HasPendingChanges,"Dados inválidos descartados silenciosamente");}});
    Test("recovery drafts are unique complete JSON backups",delegate{string folder=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"mello-recovery-test-"+Guid.NewGuid().ToString("N"));string a=null,b=null;try{ChartDocument d=ChartCore.Example("buildup");d.rows[0].actual=.30000000000000004;d.style="dark";a=RecoveryStore.SaveTo(folder,d);b=RecoveryStore.SaveTo(folder,d);Is(a!=b,"Rascunho sobrescrito");Is(ChartCore.Serialize(ChartCore.Deserialize(System.IO.File.ReadAllText(a)))==ChartCore.Serialize(d),"Rascunho perdeu precisão ou aparência");}finally{if(a!=null)System.IO.File.Delete(a);if(b!=null)System.IO.File.Delete(b);if(System.IO.Directory.Exists(folder))System.IO.Directory.Delete(folder,false);}});
    Test("native owner loss saves draft and disposes the invisible editor",delegate{
      string folder=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"mello-owner-test-"+Guid.NewGuid().ToString("N"));NativeOwner owner=new NativeOwner();
      try{using(EditorForm editor=new EditorForm(null,ChartCore.Example("columns"),null)){
        FieldInfo recovery=typeof(EditorForm).GetField("recoveryFolder",BindingFlags.NonPublic|BindingFlags.Instance);Is(recovery!=null,"Destino de recuperação não configurável no teste");recovery.SetValue(editor,folder);
        var title=(System.Windows.Forms.TextBox)typeof(EditorForm).GetField("title",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(editor);title.Text="Edição ainda não aplicada";
        editor.ShowInTaskbar=false;editor.Opacity=0;editor.Show(owner);System.Windows.Forms.Application.DoEvents();owner.Destroy();System.Windows.Forms.Application.DoEvents();
        Is(System.IO.Directory.Exists(folder) && System.IO.Directory.GetFiles(folder,"*.json").Length==1,"Rascunho perdido quando HWND do dono foi destruído");string file=System.IO.Directory.GetFiles(folder,"*.json")[0];Is(ChartCore.Deserialize(System.IO.File.ReadAllText(file)).title=="Edição ainda não aplicada","Rascunho antigo");Is(editor.IsDisposed,"Editor permaneceu vivo e invisível");
      }}finally{owner.Destroy();if(System.IO.Directory.Exists(folder)){foreach(string file in System.IO.Directory.GetFiles(folder))System.IO.File.Delete(file);System.IO.Directory.Delete(folder,false);}}
    });
    Test("cross-deck insert rejects before any shape or undo mutation",delegate{NativeApp app=new NativeApp();object context=Call("CaptureContext",app);NativeDeck other=new NativeDeck();app.Presentations.Items.Add(other);app.ActivePresentation=other;app.ActiveWindow.View.Slide=other.Slides.Items[0];Reject(delegate{Call("InsertInContext",app,ChartCore.Example("columns"),null,context);});Is(other.Slides.Items[0].Shapes.Count==0 && app.UndoEntries==0,"Alteração no arquivo errado");});
    Test("fit failure restores original dimensions rotation and position",delegate{NativeApp app=new NativeApp();Call("InsertOrUpdate",app,ChartCore.Example("columns"),null);FakeShape shape=app.ActiveWindow.View.Slide.Shapes[1];shape.Left=72;shape.Top=61;shape.Width=500;shape.Height=280;shape.Rotation=12;shape.LockAspectRatio=0;app.ActiveWindow.Selection.Items=new[]{shape};shape.FailNextHeight=true;Reject(delegate{Call("FitSelected",app);});Near(shape.Left,72);Near(shape.Top,61);Near(shape.Width,500);Near(shape.Height,280);Near(shape.Rotation,12);Is(shape.LockAspectRatio==0,"Proporção original alterada após falha");});
    Console.WriteLine(passed+" integration checks passed; "+failed+" failed");return failed==0?0:1;
  }
}
public sealed class NativePages { public double SlideWidth=960,SlideHeight=540; }
public sealed class NativeDeck {public NativePages PageSetup=new NativePages();public NativeSlides Slides=new NativeSlides();public NativeDeck(){AddSlide(42);}public FakeSlide AddSlide(int id){FakeSlide slide=new FakeSlide{SlideID=id,Parent=this};Slides.Items.Add(slide);return slide;}}
public sealed class NativeSlides {public List<FakeSlide> Items=new List<FakeSlide>();public int Count{get{return Items.Count;}}public FakeSlide FindBySlideID(int id){return Items.Single(s=>s.SlideID==id);}}
public sealed class NativeDecks {public List<NativeDeck> Items=new List<NativeDeck>();public int Count{get{return Items.Count;}}public NativeDeck this[int index]{get{return Items[index-1];}}}
public sealed class NativeView {public FakeSlide Slide;}
public sealed class NativeWindow {public NativeView View=new NativeView();public NativeSelection Selection=new NativeSelection();public int HWND=0;}
public sealed class NativeSelection {public int Type=2;public bool HasChildShapeRange=false;public FakeShape[] Items=new FakeShape[0];public NativeRange ShapeRange{get{return new NativeRange(Items);}}public NativeRange ChildShapeRange{get{return new NativeRange(Items);}}}
public sealed class NativeRange {readonly FakeShape[] items;public NativeRange(FakeShape[] values){items=values;}public int Count{get{return items.Length;}}public FakeShape this[int index]{get{return items[index-1];}}}
public sealed class NativeApp {public NativeDecks Presentations=new NativeDecks();public NativeDeck ActivePresentation;public NativeWindow ActiveWindow=new NativeWindow();public int UndoEntries;public NativeApp(){ActivePresentation=new NativeDeck();Presentations.Items.Add(ActivePresentation);ActiveWindow.View.Slide=ActivePresentation.Slides.Items[0];}public void StartNewUndoEntry(){UndoEntries++;}}
public sealed class NativeRibbon {public int Invalidations;public void Invalidate(){Invalidations++;}}
public sealed class NativeOwner:System.Windows.Forms.NativeWindow,System.Windows.Forms.IWin32Window {public NativeOwner(){CreateHandle(new System.Windows.Forms.CreateParams{Caption="Mello Charts lifecycle test",Style=0x00CF0000});}public void Destroy(){if(Handle!=IntPtr.Zero)DestroyHandle();}}
